/**
 * RetroGamingPC colour themes (high-contrast dark mode). The palettes live in
 * themePalettes.json — generated by scripts/generate-theme-palettes.py and read
 * by both this module and tailwind.config.js (which maps every token to a CSS
 * variable).
 *
 * Surfaces are tinted by the theme hue; text tokens (text, textBright,
 * textMuted, ink) are neutral greys identical in every theme. Non-default
 * palettes hold each surface's relative luminance equal to olive's, so contrast
 * is the same everywhere (enforced by src/utils/__tests__/themes.test.ts).
 */
import palettes from './themePalettes.json';

export type ThemeName = 'olive' | 'blue' | 'red' | 'yellow' | 'pink';

/** Settings order; the default comes first. */
export const THEME_NAMES: readonly ThemeName[] = ['blue', 'olive', 'red', 'yellow', 'pink'];
export const DEFAULT_THEME: ThemeName = 'blue';

/**
 * Names shown in Settings. The ids (blue, olive, …) stay as they are: they are
 * stored in profiles.ui_theme and used throughout the code.
 */
export const THEME_LABELS: Record<ThemeName, string> = {
  blue: 'Mega',
  olive: 'Chief',
  red: 'Super',
  yellow: 'Pika',
  pink: 'Peach',
};

/** Token names as used in Tailwind classes (`bg-retrogamingpc-<token>`). */
export type ThemeToken = keyof (typeof palettes)['olive'];

export const THEME_TOKENS = Object.keys(palettes.olive) as ThemeToken[];

/** JS-side palette (camelCase keys) for navigator options, icon colours, etc. */
export type ThemePalette = {
  dark: string;
  card: string;
  panel: string;
  accent: string;
  highlight: string;
  text: string;
  textBright: string;
  textMuted: string;
  button: string;
  buttonBorder: string;
  active: string;
  bevelLight: string;
  bevelDark: string;
  /** Neutral near-black for text on light coloured surfaces (badges). */
  ink: string;
};

/** Text tokens: neutral and identical across themes (no colour tint on text). */
export const NEUTRAL_TEXT_TOKENS = ['text-bright', 'text', 'text-muted', 'ink'] as const;

const camel = (token: string) => token.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());

export function isThemeName(value: unknown): value is ThemeName {
  return typeof value === 'string' && (THEME_NAMES as readonly string[]).includes(value);
}

/** Hex palette for a theme. */
export function themePalette(name: ThemeName): ThemePalette {
  const source = palettes[name] as Record<ThemeToken, string>;
  return Object.fromEntries(THEME_TOKENS.map((t) => [camel(t), source[t]])) as ThemePalette;
}

/** "#3a3d36" → "58 61 54". */
export function hexToTriplet(hex: string): string {
  return [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16)).join(' ');
}

/** CSS variable assignments for a theme (`--rgpc-<token>: "r g b"`). */
export function themeCssVariables(name: ThemeName): Record<`--rgpc-${ThemeToken}`, string> {
  const source = palettes[name] as Record<ThemeToken, string>;
  return Object.fromEntries(THEME_TOKENS.map((t) => [`--rgpc-${t}`, hexToTriplet(source[t])])) as Record<
    `--rgpc-${ThemeToken}`,
    string
  >;
}
